<?php
declare(strict_types=1);
namespace LeafPHP\Core;
use LeafPHP\Database\QueryLog;
final class DebugToolbar
{
 public static function inject(string $html,float $startedAt,Request $request): string
 {
  if (config('app.env','local')==='production'||!config('app.debug',false)||$request->isJson()) return $html;
  $contentType=strtolower(implode(';',headers_list()));
  if (str_contains($contentType,'application/json')||str_contains($contentType,'text/plain')||(!str_contains(strtolower($html),'<html')&&!str_contains(strtolower($html),'<!doctype html')&&!str_contains(strtolower($html),'<body'))) return $html;
  $queries=QueryLog::all();$total=0.0;foreach($queries as $q)$total+=(float)$q['time_ms'];
  $data=['environment'=>config('app.env','local'),'debug'=>true,'php'=>PHP_VERSION,'server_software'=>(string)($_SERVER['SERVER_SOFTWARE']??'unknown'),'method'=>$request->method(),'url'=>$request->url(),'ip'=>$request->ip(),'user_agent'=>$request->userAgent(),'route'=>Router::current(),'routes'=>Router::routes(),'queries'=>$queries,'query_time_ms'=>round($total,3),'elapsed_ms'=>round((microtime(true)-$startedAt)*1000,2),'memory'=>self::bytes(memory_get_peak_usage(true)),'session'=>self::safeSession($_SESSION??[]),'logs'=>self::recentLogs()];
  $json=json_encode($data,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP|JSON_UNESCAPED_SLASHES|JSON_PARTIAL_OUTPUT_ON_ERROR);
  $toolbar='<div id="leaf-debug-root"><button id="leaf-debug-toggle" type="button">LeafPHP <b>'.count($queries).' queries</b> · '.e((string)$data['elapsed_ms']).' ms</button><section id="leaf-debug-panel" hidden><header><strong>LeafPHP Debug</strong><button id="leaf-debug-close" type="button" aria-label="Close">×</button></header><nav id="leaf-debug-tabs"><button data-tab="overview">Overview</button><button data-tab="queries">Queries ('.count($queries).')</button><button data-tab="routes">Routes</button><button data-tab="session">Session</button><button data-tab="logs">Logs</button><button data-tab="request">Request</button><button data-tab="environment">Environment</button></nav><div id="leaf-debug-content"></div></section></div>';
  $css='<style id="leaf-debug-css">#leaf-debug-root{font:13px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:#171717}#leaf-debug-toggle{position:fixed;z-index:2147483000;bottom:0;left:14px;border:1px solid #444;border-bottom:0;border-radius:8px 8px 0 0;background:#171717;color:#fff;padding:10px 14px;box-shadow:0 2px 18px #0003;cursor:pointer}#leaf-debug-toggle b{font-weight:600;color:#cfcfcf}#leaf-debug-panel{position:fixed;z-index:2147482999;bottom:42px;left:12px;right:12px;max-height:55vh;overflow:hidden;background:#fff;border:1px solid #bbb;border-radius:10px;box-shadow:0 8px 40px #0004;color:#171717}#leaf-debug-panel header{display:flex;justify-content:space-between;padding:12px 16px;border-bottom:1px solid #ddd}#leaf-debug-panel button{font:inherit;cursor:pointer}#leaf-debug-close{border:0;background:transparent;font-size:22px}#leaf-debug-tabs{display:flex;gap:4px;flex-wrap:wrap;padding:8px;border-bottom:1px solid #ddd;background:#f6f6f6}#leaf-debug-tabs button{border:1px solid #ccc;border-radius:5px;background:#fff;padding:6px 10px}#leaf-debug-content{padding:12px 16px;overflow:auto;max-height:calc(55vh - 104px)}#leaf-debug-content table{border-collapse:collapse;width:100%;font-size:12px}#leaf-debug-content th,#leaf-debug-content td{text-align:left;vertical-align:top;padding:7px;border-bottom:1px solid #e5e5e5;overflow-wrap:anywhere}#leaf-debug-content pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f6f6;padding:10px;border-radius:5px;margin:0}#leaf-debug-content .leaf-debug-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}#leaf-debug-content .leaf-debug-card{border:1px solid #ddd;border-radius:7px;padding:10px}#leaf-debug-content .leaf-debug-muted{color:#666}@media(max-width:600px){#leaf-debug-panel{left:0;right:0;bottom:39px;max-height:65vh;border-radius:9px 9px 0 0}#leaf-debug-content{max-height:calc(65vh - 104px)}} </style>';
  $script='<script>(function(){const d='.$json.';const root=document.getElementById("leaf-debug-root"),panel=document.getElementById("leaf-debug-panel"),content=document.getElementById("leaf-debug-content");if(!root)return;const esc=s=>String(s??"").replace(/[&<>"\']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","\'":"&#39;"}[c]));const pretty=x=>JSON.stringify(x,null,2);function render(tab){let out="";if(tab==="overview")out=`<div class="leaf-debug-grid"><div class="leaf-debug-card"><b>Environment</b><p>${esc(d.environment)}</p></div><div class="leaf-debug-card"><b>Request</b><p>${esc(d.method)} ${esc(d.url)}</p></div><div class="leaf-debug-card"><b>Execution time</b><p>${esc(d.elapsed_ms)} ms</p></div><div class="leaf-debug-card"><b>Memory peak</b><p>${esc(d.memory)}</p></div><div class="leaf-debug-card"><b>Queries</b><p>${d.queries.length} · ${esc(d.query_time_ms)} ms total</p></div><div class="leaf-debug-card"><b>Matched route</b><p>${esc(d.route?.name||d.route?.uri||"No matched route")}</p></div></div>`;else if(tab==="queries")out=d.queries.length?`<table><thead><tr><th>#</th><th>SQL</th><th>Bindings</th><th>Time</th><th>Connection</th></tr></thead><tbody>${d.queries.map((q,i)=>`<tr><td>${i+1}</td><td><pre>${esc(q.sql)}</pre></td><td><pre>${esc(pretty(q.bindings))}</pre></td><td>${esc(q.time_ms)} ms</td><td>${esc(q.connection)}</td></tr>`).join("")}</tbody></table>`:"No database queries were recorded.";else if(tab==="routes")out=`<table><thead><tr><th>Method</th><th>URI</th><th>Name</th><th>Action</th></tr></thead><tbody>${d.routes.map(r=>`<tr><td>${esc(r.method)}</td><td>${esc(r.uri)}</td><td>${esc(r.name||"—")}</td><td>${esc(r.action)}</td></tr>`).join("")}</tbody></table>`;else if(tab==="session")out=`<p class="leaf-debug-muted">Sensitive values such as passwords, tokens, CSRF secrets and cookies are redacted.</p><pre>${esc(pretty(d.session))}</pre>`;else if(tab==="logs")out=`<pre>${esc(d.logs.length?d.logs.join("\n"):"No application log entries found.")}</pre>`;else if(tab==="request")out=`<div class="leaf-debug-grid"><div class="leaf-debug-card"><b>Client IP</b><p>${esc(d.ip)}</p></div><div class="leaf-debug-card"><b>User agent</b><p>${esc(d.user_agent)}</p></div></div><h4>Request details</h4><pre>${esc(pretty({method:d.method,url:d.url,route:d.route}))}</pre>`;else out=`<pre>${esc(pretty({environment:d.environment,debug:d.debug,php:d.php,server_software:d.server_software}))}</pre>`;content.innerHTML=out;}document.getElementById("leaf-debug-toggle").addEventListener("click",()=>{panel.hidden=!panel.hidden;if(!panel.hidden)render("overview")});document.getElementById("leaf-debug-close").addEventListener("click",()=>panel.hidden=true);document.querySelectorAll("#leaf-debug-tabs button").forEach(b=>b.addEventListener("click",()=>render(b.dataset.tab)));})();</script>';
  $fragment=$css.$toolbar.$script;
  if(preg_match('/<\/body\s*>/i',$html))return preg_replace('/<\/body\s*>/i',$fragment.'$0',$html,1)??$html.$fragment;
  return $html.$fragment;
 }
 private static function safeSession(array $session): array { $out=[];foreach($session as $key=>$value){$name=(string)$key;if(preg_match('/password|secret|token|csrf|cookie|authorization|api.?key/i',$name)){$out[$name]='[redacted]';continue;}$out[$name]=self::safeValue($value,0);}return $out; }
 private static function safeValue(mixed $value,int $depth): mixed { if($depth>4)return '[max depth]';if(is_array($value)){ $out=[];foreach(array_slice($value,0,50,true) as $k=>$v){if(preg_match('/password|secret|token|csrf|cookie|authorization|api.?key/i',(string)$k))$out[$k]='[redacted]';else$out[$k]=self::safeValue($v,$depth+1);}return $out;}if(is_object($value))return '[object '.get_class($value).']';if(is_resource($value))return '[resource]';if(is_string($value)&&strlen($value)>500)return substr($value,0,497).'...';return $value; }
 private static function recentLogs(): array { $dir=dirname(__DIR__,2).'/storage/logs';$files=glob($dir.'/*.log')?:[];rsort($files);$lines=[];foreach(array_slice($files,0,3) as $file){$content=@file($file,FILE_IGNORE_NEW_LINES);if(!$content)continue;foreach(array_slice($content,-80) as $line){$line=preg_replace('/(password|token|secret|authorization|api[_-]?key)(\s*[=:]\s*)[^,; ]+/i','$1$2[redacted]',$line)??$line;$lines[]=$line;}}return array_slice($lines,-120); }
 private static function bytes(int $bytes): string { if($bytes>=1048576)return round($bytes/1048576,2).' MB';if($bytes>=1024)return round($bytes/1024,1).' KB';return $bytes.' B'; }
}
